CREATE OR REPLACE FUNCTION public.combat_enemy_act(p_atk numeric, p_bmult numeric, p_round integer, p_stun_until integer, p_lost numeric, p_share bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
