    v_act := 'stunned';
  elsif p_round % v_cyc = v_cyc - 1 then
    v_act := 'charging';                      -- the Cataclysm is shown one round ahead
  elsif p_round % v_cyc = 0 then
    v_act := 'cataclysm';                     -- ATK x cataclysm_x to every card still standing
