      v_cdmg := greatest(1, round(p_atk * (m->>'stun_x')::numeric * (public.balance_num('combat', 'roll_min') + random() * public.balance_num('combat', 'roll_span')) * p_bmult));
    elsif v_r < v_t5 then
      v_act := 'enrage';                      -- x enrage_x for enrage_rounds (the caller stores it)
    elsif v_r < v_t6 then
